import { test } from "node:test";
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import net from "node:net";
import path from "node:path";
import url from "node:url";

const __dirname = path.dirname(url.fileURLToPath(import.meta.url));
const serverPath = path.join(__dirname, "..", "dist", "server.js");

function getFreePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.listen(0, () => {
      const { port } = srv.address();
      srv.close(() => resolve(port));
    });
    srv.on("error", reject);
  });
}

test("running the entry point starts listening and logs the base URL", async () => {
  const port = await getFreePort();
  const baseUrl = `http://localhost:${port}`;

  const child = spawn(process.execPath, [serverPath], {
    env: { ...process.env, PORT: String(port), BASE_URL: baseUrl },
    stdio: ["ignore", "pipe", "pipe"],
  });

  let stdout = "";
  child.stdout.on("data", (chunk) => {
    stdout += chunk.toString();
  });
  let stderr = "";
  child.stderr.on("data", (chunk) => {
    stderr += chunk.toString();
  });

  try {
    await new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error(`Server did not log the base URL in time. stderr: ${stderr}`));
      }, 2000);
      child.stdout.on("data", function check() {
        if (stdout.includes(baseUrl)) {
          clearTimeout(timer);
          child.stdout.removeListener("data", check);
          resolve();
        }
      });
      child.on("error", (err) => {
        clearTimeout(timer);
        reject(err);
      });
      child.on("exit", (code) => {
        if (!stdout.includes(baseUrl)) {
          clearTimeout(timer);
          reject(new Error(`Server exited early (code ${code}). stderr: ${stderr}`));
        }
      });
    });

    assert.match(stdout, new RegExp(baseUrl.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")));

    const res = await fetch(`${baseUrl}/health`);
    assert.equal(res.status, 200);
    const body = await res.json();
    assert.deepEqual(body, { status: "ok" });
  } finally {
    child.kill();
  }
});
